message.content:
{
  "title": "Rescue Through the Mirror City",
  "scenes": [
    {
      "scene_number": 1,
      "caption": "Mara studies a ruined gate.",
      "visual_description": "A crumbling archway with broken royal banners, Mara the Cartographer stands before it, compass in hand, ink-stained coat flapping in a dry wind.",
      "characters": ["mara_the_cartographer"]
    },
    {
      "scene_number": 2,
      "caption": "The Glass Diver tests a window.",
      "visual_description": "A clear diving helmet reflecting shattered stained glass, the Glass Diver taps a fractured window pane, ripples spreading across its surface.",
      "characters": ["glass_diver"]
    },
    {
      "scene_number": 3,
      "caption": "Tin Fox scouts the courtyard.",
      "visual_description": "A small clockwork fox with blue glass eyes winds between broken flagstones, key-wind tail ticking, sniffing at fallen banners.",
      "characters": ["tin_fox"]
    },
    {
      "scene_number": 4,
      "caption": "Oracle Lamp warns of a cursed tower.",
      "visual_description": "An oil lamp with a single glowing eye in its flame flickers urgently, casting long shadows from a twisted spire ahead.",
      "characters": ["oracle_lamp"]
    },
    {
      "scene_number": 5,
      "caption": "Mara draws the route through the city.",
      "visual_description": "Mara kneels over a parchment map, ink-stained fingers tracing a path past a black tower, compass needle spinning.",
      "characters": ["mara_the_cartographer"]
    },
    {
      "scene_number": 6,
      "caption": "Glass Diver swims through a window into a locked room.",
      "visual_description": "The Glass Diver passes through a glass pane like water, emerging inside a dust-choked chamber with sealed doors.",
      "characters": ["glass_diver"]
    },
    {
      "scene_number": 7,
      "caption": "Tin Fox discovers a patrol route.",
      "visual_description": "Tin Fox’s blue glass eyes glow as it peers around a corner, catching the gleam of armored figures in the distance.",
      "characters": ["tin_fox"]
    },
    {
      "scene_number": 8,
      "caption": "Oracle Lamp warns of an armored patrol ahead.",
      "visual_description": "The lamp's eye narrows, flame dimming, as it whispers of metal footsteps echoing from a nearby street.",
      "characters": ["oracle_lamp"]
    },
    {
      "scene_number": 9,
      "caption": "The party hides behind fallen royal banners.",
      "visual_description": "Mara, Glass Diver, Tin Fox, and Oracle Lamp crouch under heavy tattered cloth, breathing shallow as boots clank past.",
      "characters": ["mara_the_cartographer", "glass_diver", "tin_fox", "oracle_lamp"]
    },
    {
      "scene_number": 10,
      "caption": "Sleeping Tax Collector snores on a ledge.",
      "visual_description": "A dozing figure in a suit stamped with papers, head on a ledger book, oblivious to the danger around him.",
      "characters": ["sleeping_tax_collector"]
    },
    {
      "scene_number": 11,
      "caption": "Glass Diver opens a magic door through reflection.",
      "visual_description": "The Glass Diver presses a hand against a mirror set in a stone arch, the surface ripples and becomes a doorway.",
      "characters": ["glass_diver"]
    },
    {
      "scene_number": 12,
      "caption": "Mara navigates through a labyrinth of mirrors.",
      "visual_description": "Mara holds the compass, its needle spinning wildly, as reflections of the party multiply in every direction.",
      "characters": ["mara_the_cartographer", "glass_diver", "tin_fox", "oracle_lamp"]
    },
    {
      "scene_number": 13,
      "caption": "Tin Fox disables a trap near a treasure room.",
      "visual_description": "Tin Fox’s metal tail inserts into a floor mechanism, gears click, and a spike ceiling halts above them.",
      "characters": ["tin_fox"]
    },
    {
      "scene_number": 14,
      "caption": "Oracle Lamp reveals the true path to the bridge.",
      "visual_description": "The lamp’s flame burns brighter, casting a beam of light down a hidden corridor lined with old banners.",
      "characters": ["oracle_lamp"]
    },
    {
      "scene_number": 15,
      "caption": "Sleeping Tax Collector rolls off the ledge, awake.",
      "visual_description": "The collector tumbles, ledger flying, and lands groggily on a pile of rubble, blinking at the party.",
      "characters": ["sleeping_tax_collector"]
    },
    {
      "scene_number": 16,
      "caption": "The group crosses the final bridge.",
      "visual_description": "A narrow stone bridge over a chasm, broken royal banners hanging from its rails, the party hurries across as the city crumbles behind.",
      "characters": ["mara_the_cartographer", "glass_diver", "tin_fox", "oracle_lamp", "sleeping_tax_collector"]
    },
    {
      "scene_number": 17,
      "caption": "Armored figures block the far end of the bridge.",
      "visual_description": "Shapes in metal armor step onto the bridge from the far side, weapons drawn, blocking escape.",
      "characters": ["mara_the_cartographer", "glass_diver", "tin_fox", "oracle_lamp", "sleeping_tax_collector"]
    },
    {
      "scene_number": 18,
      "caption": "Glass Diver shatters the bridge behind them.",
      "visual_description": "The Glass Diver sinks a hand into a mirror shard on the bridge, the entire structure cracks and falls, leaving only the party on safe ground.",
      "characters": ["mara_the_cartographer", "glass_diver", "tin_fox", "oracle_lamp", "sleeping_tax_collector"]
    }
  ]
}

